insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه دور factory constructor في Dart مقارنة بالـgenerative constructor؟', 'الـgenerative constructor ينشئ instance من نفس الكلاس، بينما factory يمكنه إرجاع instance موجودة أو من subclass أو تنفيذ منطق اختيار قبل الإرجاع.', 'استخدم generative constructor عندما تريد إنشاء object وتهيئة حقوله مباشرة. factory لا يملك وصولًا مباشرًا إلى this قبل الإرجاع، لكنه مناسب للـcaching أو parsing أو اختيار implementation. وجود factory لا يعني تلقائيًا أن هناك singleton؛ القرار يعتمد على منطق الكلاس.', 'class User {
  final String id;
  User._(this.id);

  factory User.fromJson(Map<String, Object?> json) {
    return User._(json["id"]! as String);
  }
