insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف تضيف سلوكًا لنوع موجود باستخدام extension في Dart؟', 'extension تضيف ميثودز أو getters لنوع موجود من غير تعديل الكلاس الأصلي أو إنشاء subclass، وتُحسم الاستدعاءات حسب النوع الثابت.', 'الـextension مفيدة لتجميع تحويل أو سلوك صغير قريب من النوع الذي يعمل عليه. هي لا تضيف state ولا تغيّر واجهة الكلاس فعليًا، كما أن اختيار extension يعتمد على static type؛ لذلك لا تستخدمها لبناء polymorphism يحتاج dispatch وقت التشغيل.', 'extension StringParsing on String {
  int? toSafeInt() => int.tryParse(this);
}

final count = "42".toSafeInt();', '["توقع أن extension تضيف حقولًا أو state للكائن.","نسيان تأثير static type عند وجود extension بنفس الاسم."]'::jsonb, '["ما الفرق بين extension وmixin في هدف التصميم؟"]'::jsonb, '[{"title":"Dart language — Extension methods","url":"https://dart.dev/language/extension-methods"}]'::jsonb from public.question_revisions r where r.question_id = 'dart-011' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
