insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي async و await بيتعاملوا مع Future في Dart؟', 'الدالة async ترجع Future، وawait ينتظر اكتمال Future داخل الدالة من غير حجز خيط التنفيذ، مع تمرير النتيجة أو الخطأ بشكل واضح.', 'Future يمثل نتيجة قد تصل لاحقًا. await يوقف استكمال الدالة الحالية حتى تكتمل العملية، لكنه لا يحول العملية إلى synchronous ولا يجمّد event loop. تعامل مع الأخطاء باستخدام try/catch، وتأكد أن كل Future مهم إما awaited أو تتم إدارته صراحة.', 'Future<String> loadName() async {
  final response = await fetchName();
  return response;
}

try {
  final name = await loadName();
} catch (error) {
  handle(error);
}', '["اعتبار await معناه تشغيل العملية على isolate آخر.","نسيان await ثم التعامل مع Future كأنه القيمة النهائية."]'::jsonb, '["إمتى تستخدم Future.wait بدل انتظار العمليات واحدة تلو الأخرى؟"]'::jsonb, '[{"title":"Dart language — Asynchronous programming","url":"https://dart.dev/language/async"}]'::jsonb from public.question_revisions r where r.question_id = 'dart-012' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
