  final response = await fetchName();
  return response;
}

try {
  final name = await loadName();
} catch (error) {
  handle(error);
}' or l.common_mistakes is distinct from '["اعتبار await معناه تشغيل العملية على isolate آخر.","نسيان await ثم التعامل مع Future كأنه القيمة النهائية."]'::jsonb or l.follow_up_questions is distinct from '["إمتى تستخدم Future.wait بدل انتظار العمليات واحدة تلو الأخرى؟"]'::jsonb or l.sources is distinct from '[{"title":"Dart language — Asynchronous programming","url":"https://dart.dev/language/async"}]'::jsonb)) then raise exception 'Question dart-012 ar content changed; create a new revision before seeding'; end if; end $$;
