insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه الفرق بين class و object في Dart؟', 'الـclass هو تعريف للبيانات والسلوك، والـobject هو instance فعلية منشأة من هذا التعريف.', 'الكلاس يحدد الحقول والميثودز والـconstructors التي تشترك فيها instances. عند استدعاء constructor ينشئ Dart object له state مستقل، حتى لو كان أكثر من object مبنيًا من نفس الكلاس.', 'class Candidate {
