insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي نطبق Encapsulation في Dart؟', 'نخفي تفاصيل التغيير خلف API صغيرة، وتُعد الأسماء التي تبدأ بـ _ خاصة بالـlibrary في Dart.', 'Encapsulation ليست مجرد جعل الحقول private؛ الفكرة أن الكلاس يحافظ على invariants ويمنح المستهلك عمليات صحيحة لتعديل state. خصوصية Dart مرتبطة بالـlibrary، لذلك صمّم حدود الملفات والواجهات بعناية ولا تعتمد على setter لكل حقل.', 'class Score {
  int _value = 0;

  void add(int points) {
    if (points > 0) _value += points;
  }

  int get value => _value;
}', '["تعريض كل state عبر public setters وإضاعة قواعد الكلاس.","اعتبار _private على مستوى object فقط؛ هو private للـlibrary."]'::jsonb, '["متى يكون getter محسوبًا أفضل من كشف field؟"]'::jsonb, '[{"title":"Dart language — Classes","url":"https://dart.dev/language/classes"}]'::jsonb from public.question_revisions r where r.question_id = 'oop-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'oop-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي نطبق Encapsulation في Dart؟' or l.short_answer is distinct from 'نخفي تفاصيل التغيير خلف API صغيرة، وتُعد الأسماء التي تبدأ بـ _ خاصة بالـlibrary في Dart.' or l.explanation is distinct from 'Encapsulation ليست مجرد جعل الحقول private؛ الفكرة أن الكلاس يحافظ على invariants ويمنح المستهلك عمليات صحيحة لتعديل state. خصوصية Dart مرتبطة بالـlibrary، لذلك صمّم حدود الملفات والواجهات بعناية ولا تعتمد على setter لكل حقل.' or l.code_example is distinct from 'class Score {
  int _value = 0;

  void add(int points) {
    if (points > 0) _value += points;
  }

