  @override int get hashCode => Object.hash(x, y);
}', '["override == من غير hashCode.","استخدام mutable fields في hashCode ثم تعديلها داخل Set أو Map."]'::jsonb, '["لماذا يجب فحص runtime type قبل مقارنة الحقول؟"]'::jsonb, '[{"title":"Dart API — Object ==","url":"https://api.dart.dev/dart-core/Object/operator_equals.html"},{"title":"Dart API — Object.hashCode","url":"https://api.dart.dev/dart-core/Object/hashCode.html"}]'::jsonb from public.question_revisions r where r.question_id = 'oop-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
