insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي نستخدم مبادئ SOLID من غير ما نحمّل Widget مسؤوليات زائدة؟', 'خلّي Widget ينسق rendering والتفاعل، ومرّر state أو callbacks واضحة بدل جعلها تقرأ الشبكة وتقرر قواعد المجال.', 'Flutter يشجع composition، لذلك فصل العرض عن state والبيانات غالبًا أوضح من توريث Widgets مخصصة. خذ القرار على أساس أسباب التغيير واختباراتك، لا على أسماء طبقات ثابتة؛ شاشة صغيرة قد لا تحتاج architecture كاملة.', null, '["وضع كل منطق التطبيق داخل build لأن الوصول إلى context سهل.","نسخ Widget tree عميقة لإخفاء مسؤوليات مختلطة."]'::jsonb, '["ما الذي يبقى داخل StatefulWidget حتى بعد فصل state؟"]'::jsonb, '[{"title":"Flutter docs — Architectural overview","url":"https://docs.flutter.dev/app-architecture/guide"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb from public.question_revisions r where r.question_id = 'solid-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'solid-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي نستخدم مبادئ SOLID من غير ما نحمّل Widget مسؤوليات زائدة؟' or l.short_answer is distinct from 'خلّي Widget ينسق rendering والتفاعل، ومرّر state أو callbacks واضحة بدل جعلها تقرأ الشبكة وتقرر قواعد المجال.' or l.explanation is distinct from 'Flutter يشجع composition، لذلك فصل العرض عن state والبيانات غالبًا أوضح من توريث Widgets مخصصة. خذ القرار على أساس أسباب التغيير واختباراتك، لا على أسماء طبقات ثابتة؛ شاشة صغيرة قد لا تحتاج architecture كاملة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["وضع كل منطق التطبيق داخل build لأن الوصول إلى context سهل.","نسخ Widget tree عميقة لإخفاء مسؤوليات مختلطة."]'::jsonb or l.follow_up_questions is distinct from '["ما الذي يبقى داخل StatefulWidget حتى بعد فصل state؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Architectural overview","url":"https://docs.flutter.dev/app-architecture/guide"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb)) then raise exception 'Question solid-006 ar content changed; create a new revision before seeding'; end if; end $$;
