insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('solid-007', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'هل لازم نطبق كل مبادئ SOLID في كل جزء من تطبيق Flutter؟', 'لا؛ استخدم المبدأ عندما يقلل تكلفة تغيير أو اختبار حقيقية، وإلا قد تضيف indirection وتعقيدًا بلا عائد.', 'SOLID heuristics وليست checklist. في feature صغيرة، function واضحة قد تكون أفضل من خمس interfaces. راقب محاور التغيير، حجم الفريق، وعمر الكود، ثم افصل عند ظهور ضغط حقيقي بدل بناء بنية مستقبلية غير مؤكدة.', null, '["قياس جودة التصميم بعدد الملفات والـinterfaces.","استخدام SOLID ذريعة لتأجيل شحن feature بسيطة."]'::jsonb, '["كيف تكتشف أن abstraction أصبحت عبئًا؟"]'::jsonb, '[{"title":"Flutter docs — App architecture","url":"https://docs.flutter.dev/app-architecture"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb from public.question_revisions r where r.question_id = 'solid-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'solid-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'هل لازم نطبق كل مبادئ SOLID في كل جزء من تطبيق Flutter؟' or l.short_answer is distinct from 'لا؛ استخدم المبدأ عندما يقلل تكلفة تغيير أو اختبار حقيقية، وإلا قد تضيف indirection وتعقيدًا بلا عائد.' or l.explanation is distinct from 'SOLID heuristics وليست checklist. في feature صغيرة، function واضحة قد تكون أفضل من خمس interfaces. راقب محاور التغيير، حجم الفريق، وعمر الكود، ثم افصل عند ظهور ضغط حقيقي بدل بناء بنية مستقبلية غير مؤكدة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["قياس جودة التصميم بعدد الملفات والـinterfaces.","استخدام SOLID ذريعة لتأجيل شحن feature بسيطة."]'::jsonb or l.follow_up_questions is distinct from '["كيف تكتشف أن abstraction أصبحت عبئًا؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — App architecture","url":"https://docs.flutter.dev/app-architecture"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb)) then raise exception 'Question solid-007 ar content changed; create a new revision before seeding'; end if; end $$;
