insert into public.interview_questions (id, slug, track_id, difficulty) values ('fundamentals-001', 'flutter-framework-engine-and-embedder', 'flutter', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fundamentals-001', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه الفرق بين Flutter framework وengine وembedder؟', 'الـframework يوفر APIs وWidgets بلغة Dart، والـengine يرسم ويشغّل runtime، والـembedder يربط Flutter بنظام التشغيل والمنصة.', 'فصل الطبقات يوضح مكان المشكلة: كود التطبيق وWidgets في framework، rasterization وDart runtime في engine، ونافذة التطبيق ودورة الحياة وإدخال المنصة في embedder. لا تحتاج حفظ كل التفاصيل، لكن مهم تعرف أن Flutter ليس مكتبة Widgets فقط.', null, '["اختزال Flutter في engine الرسم فقط.","اعتبار platform embedder جزءًا من كود Widget نفسه."]'::jsonb, '["أي طبقة تتأثر عند تغيير طريقة الرسم أو منصة التشغيل؟"]'::jsonb, '[{"title":"Flutter docs — Architectural overview","url":"https://docs.flutter.dev/resources/architectural-overview"}]'::jsonb from public.question_revisions r where r.question_id = 'fundamentals-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fundamentals-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إيه الفرق بين Flutter framework وengine وembedder؟' or l.short_answer is distinct from 'الـframework يوفر APIs وWidgets بلغة Dart، والـengine يرسم ويشغّل runtime، والـembedder يربط Flutter بنظام التشغيل والمنصة.' or l.explanation is distinct from 'فصل الطبقات يوضح مكان المشكلة: كود التطبيق وWidgets في framework، rasterization وDart runtime في engine، ونافذة التطبيق ودورة الحياة وإدخال المنصة في embedder. لا تحتاج حفظ كل التفاصيل، لكن مهم تعرف أن Flutter ليس مكتبة Widgets فقط.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اختزال Flutter في engine الرسم فقط.","اعتبار platform embedder جزءًا من كود Widget نفسه."]'::jsonb or l.follow_up_questions is distinct from '["أي طبقة تتأثر عند تغيير طريقة الرسم أو منصة التشغيل؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Architectural overview","url":"https://docs.flutter.dev/resources/architectural-overview"}]'::jsonb)) then raise exception 'Question fundamentals-001 ar content changed; create a new revision before seeding'; end if; end $$;
