insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ماذا تعني Declarative UI في Flutter؟', 'تصف شكل الواجهة الناتج من state الحالية، وعندما تتغير state يعيد Flutter بناء الوصف بدل أن تطلب تعديل كل عنصر يدويًا.', 'في النموذج التصريحي تكتب ما يجب أن يظهر لحالة معينة، وFlutter يقارن شجرة Widgets الجديدة ويطبق التغيير على الواجهة. هذا يقلل أوامر mutation المتناثرة، لكنه يتطلب إدارة state ومفاتيح وهوية Widgets بشكل صحيح.', 'Widget build(BuildContext context) {
  return Text(isLoading ? "Loading" : "Ready");
}', '["اعتبار build عملية رسم مباشرة لكل بكسل.","تعديل state داخل build بدل تغييرها في حدث أو controller."]'::jsonb, '["لماذا لا يعني rebuild أن كل الشاشة تُرسم من الصفر؟"]'::jsonb, '[{"title":"Flutter docs — Declarative UI","url":"https://docs.flutter.dev/get-started/flutter-for/declarative"}]'::jsonb from public.question_revisions r where r.question_id = 'fundamentals-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fundamentals-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ماذا تعني Declarative UI في Flutter؟' or l.short_answer is distinct from 'تصف شكل الواجهة الناتج من state الحالية، وعندما تتغير state يعيد Flutter بناء الوصف بدل أن تطلب تعديل كل عنصر يدويًا.' or l.explanation is distinct from 'في النموذج التصريحي تكتب ما يجب أن يظهر لحالة معينة، وFlutter يقارن شجرة Widgets الجديدة ويطبق التغيير على الواجهة. هذا يقلل أوامر mutation المتناثرة، لكنه يتطلب إدارة state ومفاتيح وهوية Widgets بشكل صحيح.' or l.code_example is distinct from 'Widget build(BuildContext context) {
  return Text(isLoading ? "Loading" : "Ready");
}' or l.common_mistakes is distinct from '["اعتبار build عملية رسم مباشرة لكل بكسل.","تعديل state داخل build بدل تغييرها في حدث أو controller."]'::jsonb or l.follow_up_questions is distinct from '["لماذا لا يعني rebuild أن كل الشاشة تُرسم من الصفر؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Declarative UI","url":"https://docs.flutter.dev/get-started/flutter-for/declarative"}]'::jsonb)) then raise exception 'Question fundamentals-002 ar content changed; create a new revision before seeding'; end if; end $$;
