insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما المراحل الأساسية لإنتاج frame في Flutter؟', 'عند الحاجة يمر Flutter بعمليات build ثم layout ثم paint، وبعدها compositing و rasterization لإظهار frame على الشاشة.', 'الفكرة العملية هي معرفة أين تبحث عند البطء: build يحدّث وصف الواجهة، layout يحسب الأحجام والمواقع، paint يسجل أوامر الرسم، والـengine ينفذها. قد يعيد Flutter مرحلة محددة فقط أو يتداخل ترتيب العمل حسب ما تغيّر، لذلك استخدم profiling بدل افتراض سبب البطء.', null, '["ربط كل jank بمرحلة build فقط.","تحسين أرقام نظرية من غير قياس في profile mode."]'::jsonb, '["أي أدوات Flutter تساعدك في رؤية frame work؟"]'::jsonb, '[{"title":"Flutter docs — Inside Flutter","url":"https://docs.flutter.dev/resources/inside-flutter"}]'::jsonb from public.question_revisions r where r.question_id = 'fundamentals-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fundamentals-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما المراحل الأساسية لإنتاج frame في Flutter؟' or l.short_answer is distinct from 'عند الحاجة يمر Flutter بعمليات build ثم layout ثم paint، وبعدها compositing و rasterization لإظهار frame على الشاشة.' or l.explanation is distinct from 'الفكرة العملية هي معرفة أين تبحث عند البطء: build يحدّث وصف الواجهة، layout يحسب الأحجام والمواقع، paint يسجل أوامر الرسم، والـengine ينفذها. قد يعيد Flutter مرحلة محددة فقط أو يتداخل ترتيب العمل حسب ما تغيّر، لذلك استخدم profiling بدل افتراض سبب البطء.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["ربط كل jank بمرحلة build فقط.","تحسين أرقام نظرية من غير قياس في profile mode."]'::jsonb or l.follow_up_questions is distinct from '["أي أدوات Flutter تساعدك في رؤية frame work؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Inside Flutter","url":"https://docs.flutter.dev/resources/inside-flutter"}]'::jsonb)) then raise exception 'Question fundamentals-004 ar content changed; create a new revision before seeding'; end if; end $$;
