do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fundamentals-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما الفرق بين hot reload وhot restart في Flutter؟' or l.short_answer is distinct from 'hot reload يحقن تغييرات الكود ويحافظ غالبًا على state الحالية، بينما hot restart يعيد تشغيل Dart app ويفقد state الموجودة.' or l.explanation is distinct from 'Hot reload مناسب لتعديل UI أو منطق مع الاحتفاظ بمكان المستخدم، لكنه لا يعيد تنفيذ كل initialization أو يطبق تغييرات تتطلب إعادة تشغيل كاملة. استخدم hot restart عندما تحتاج دورة تشغيل جديدة، واختبر النتيجة النهائية في build مناسب.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اعتبار hot reload بديلًا لاختبار release.","الاستغراب من بقاء state قديمة بعد تعديل initialization."]'::jsonb or l.follow_up_questions is distinct from '["متى تحتاج إعادة تشغيل التطبيق أو الجهاز بالكامل؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Hot reload","url":"https://docs.flutter.dev/tools/hot-reload"}]'::jsonb)) then raise exception 'Question fundamentals-005 ar content changed; create a new revision before seeding'; end if; end $$;
