insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إمتى تستخدم debug وprofile وrelease mode في Flutter؟', 'debug للتطوير مع أدوات التشخيص، profile لقياس الأداء قريبًا من release، وrelease للتوزيع مع تحسينات وتعطيل أدوات التطوير.', 'اختيار mode يغير assertions والتشخيص والتحسينات، لذلك لا تقيس أداء التطبيق من debug. استخدم profile على جهاز حقيقي عندما تريد قياس frame أو استهلاك الموارد، ثم تحقق من سلوك release قبل النشر.', null, '["اتخاذ قرار أداء من تجربة debug فقط.","تضمين أدوات أو logs تطويرية في release بلا قصد."]'::jsonb, '["لماذا قد يختلف سلوك code path بين debug وrelease؟"]'::jsonb, '[{"title":"Flutter docs — Build modes","url":"https://docs.flutter.dev/testing/build-modes"}]'::jsonb from public.question_revisions r where r.question_id = 'fundamentals-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fundamentals-006' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إمتى تستخدم debug وprofile وrelease mode في Flutter؟' or l.short_answer is distinct from 'debug للتطوير مع أدوات التشخيص، profile لقياس الأداء قريبًا من release، وrelease للتوزيع مع تحسينات وتعطيل أدوات التطوير.' or l.explanation is distinct from 'اختيار mode يغير assertions والتشخيص والتحسينات، لذلك لا تقيس أداء التطبيق من debug. استخدم profile على جهاز حقيقي عندما تريد قياس frame أو استهلاك الموارد، ثم تحقق من سلوك release قبل النشر.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اتخاذ قرار أداء من تجربة debug فقط.","تضمين أدوات أو logs تطويرية في release بلا قصد."]'::jsonb or l.follow_up_questions is distinct from '["لماذا قد يختلف سلوك code path بين debug وrelease؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Build modes","url":"https://docs.flutter.dev/testing/build-modes"}]'::jsonb)) then raise exception 'Question fundamentals-006 ar content changed; create a new revision before seeding'; end if; end $$;
