insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('fundamentals-009', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تضيف assets وصور إلى تطبيق Flutter؟', 'تعلن المسارات في pubspec.yaml ثم تستخدم APIs المناسبة لتحميلها، ويجب أن تكون المسارات والـindentation صحيحة ضمن asset bundle.', 'Flutter لا يضم ملفًا لمجرد وجوده في repository؛ pubspec يحدد ما يدخل في asset bundle. عرّف مجلدًا أو ملفًا بوضوح، واستخدم package prefix عند استهلاك asset من package أخرى، ثم اختبر build النهائي لا hot reload فقط.', null, '["نسيان إعلان asset أو خطأ indentation في YAML.","استخدام path محلي يعمل في debug ولا يوجد داخل bundle المنشور."]'::jsonb, '["كيف تشير إلى asset موجود داخل dependency package؟"]'::jsonb, '[{"title":"Flutter docs — Assets and images","url":"https://docs.flutter.dev/ui/assets/assets-and-images"}]'::jsonb from public.question_revisions r where r.question_id = 'fundamentals-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fundamentals-009' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تضيف assets وصور إلى تطبيق Flutter؟' or l.short_answer is distinct from 'تعلن المسارات في pubspec.yaml ثم تستخدم APIs المناسبة لتحميلها، ويجب أن تكون المسارات والـindentation صحيحة ضمن asset bundle.' or l.explanation is distinct from 'Flutter لا يضم ملفًا لمجرد وجوده في repository؛ pubspec يحدد ما يدخل في asset bundle. عرّف مجلدًا أو ملفًا بوضوح، واستخدم package prefix عند استهلاك asset من package أخرى، ثم اختبر build النهائي لا hot reload فقط.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["نسيان إعلان asset أو خطأ indentation في YAML.","استخدام path محلي يعمل في debug ولا يوجد داخل bundle المنشور."]'::jsonb or l.follow_up_questions is distinct from '["كيف تشير إلى asset موجود داخل dependency package؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Assets and images","url":"https://docs.flutter.dev/ui/assets/assets-and-images"}]'::jsonb)) then raise exception 'Question fundamentals-009 ar content changed; create a new revision before seeding'; end if; end $$;
