insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تختار بين preferences وfiles وstructured local database للتخزين المحلي؟', 'استخدم preferences لإعدادات صغيرة، وfiles للمستندات أو البيانات غير المهيكلة، وdatabase للبيانات المترابطة التي تحتاج query وtransaction.', 'الاختيار يبدأ من شكل البيانات وطريقة الوصول لها، وليس من اسم package. key-value مناسب لقيم بسيطة، والملف يحافظ على blob أو مستند كامل، بينما قاعدة البيانات تضيف schema واستعلامات وعلاقات وتكلفة تشغيل وصيانة أعلى. حدّد حجم البيانات، عدد القراءات والكتابات، الحاجة إلى بحث أو migration، ثم استخدم أبسط خيار يحقق العقد.', null, '["حفظ قائمة كبيرة أو بيانات مترابطة كـkey-value واحد.","اختيار قاعدة بيانات لمجرد أن التطبيق لديه أكثر من شاشة.","اعتبار أي package حلًا عالميًا لكل أنواع التخزين."]'::jsonb, '["إمتى يتحول ملف JSON إلى عبء مقارنة بقاعدة بيانات؟"]'::jsonb, '[{"title":"Flutter cookbook — Persistence","url":"https://docs.flutter.dev/cookbook/persistence"}]'::jsonb from public.question_revisions r where r.question_id = 'storage-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
