insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إمتى تستخدم key-value preferences وما حدودها؟', 'هي مناسبة لإعدادات صغيرة primitive مثل theme أو flag، لكنها ليست مخزنًا لملفات كبيرة أو بيانات معقدة أو أسرار حساسة.', 'تخزين key-value يجعل قراءة إعداد صغير سهلة، لكن الأنواع المدعومة محدودة ولا يوفر model للعلاقات أو استعلامات غنية. صمّم مفاتيح ثابتة، تعامل مع غياب القيمة، ولا تضع tokens أو أسرارًا لمجرد أن القيمة ستبقى بعد إعادة تشغيل التطبيق؛ اختر تخزينًا آمنًا عندما تكون السرية جزءًا من المتطلب.', 'final prefs = await SharedPreferences.getInstance();
await prefs.setBool("dark_mode", true);
final enabled = prefs.getBool("dark_mode") ?? false;', '["استخدام preferences لتخزين cache كبير أو JSON ضخم.","افتراض أن الكتابة تعني ضمانًا مطلقًا لبقاء البيانات.","حفظ secret أو access token في مخزن غير مخصص للأسرار."]'::jsonb, '["كيف تختبر كود preferences من غير الاعتماد على disk حقيقي؟"]'::jsonb, '[{"title":"Flutter cookbook — Store key-value data on disk","url":"https://docs.flutter.dev/cookbook/persistence/key-value"}]'::jsonb from public.question_revisions r where r.question_id = 'storage-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
