insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى تكون SQLite أو structured local database مناسبة في تطبيق Flutter؟', 'عندما تكون البيانات كثيرة أو مترابطة وتحتاج استعلامًا وفرزًا وتحديثًا متكررًا، مع schema وversioning واضحين.', 'قاعدة البيانات تكسب عندما تصبح القراءة الانتقائية والعلاقات والـtransactions أهم من بساطة ملف واحد. صمّم الجداول والمفاتيح، حدّد migrations عند تغيير schema، واعزل API الخاصة بالقاعدة خلف repository أو data source. اختيار SQLite أو engine آخر يتبع المنصات والمتطلبات؛ لا تجعل اسم package هو القرار المعماري نفسه.', 'final database = await openDatabase(
