    "CREATE TABLE notes(id INTEGER PRIMARY KEY, body TEXT)",
  ),
);' or l.common_mistakes is distinct from '["وضع SQL وdatabase handles داخل Widgets.","تغيير schema من غير migration أو version.","استخدام database بينما احتياج feature مجرد setting واحدة."]'::jsonb or l.follow_up_questions is distinct from '["ما الذي يجب أن يحدث عند فتح نسخة أقدم من قاعدة البيانات؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter cookbook — Persist data with SQLite","url":"https://docs.flutter.dev/cookbook/persistence/sqlite"}]'::jsonb)) then raise exception 'Question storage-004 ar content changed; create a new revision before seeding'; end if; end $$;
