insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إمتى تختار plugin جاهزًا أو custom platform integration؟', 'ابدأ بـFlutter API أو plugin موثوق، واكتب integration مخصصًا فقط عندما توجد capability حقيقية غير مغطاة، مع عزل اختلافات المنصات خلف contract واحد.', 'الـplugin الجاهز يقلل native code والصيانة، لكن يجب فحص المنصات المدعومة والـlifecycle وجودة الصيانة. عند الحاجة المخصصة، يمكن بناء plugin أو channel وربط Dart بالـhost، مع تنفيذ fallback أو رفض واضح للمنصة غير المدعومة. هذا قرار boundary وتكلفة ملكية، وليس قاعدة أن package واحدة أفضل دائمًا.', null, '["إضافة native code قبل التحقق من Flutter API أو plugin مناسب.","كشف تفاصيل Android وiOS في كل مستهلك بدل adapter واحد.","التعامل مع capability غير المدعومة كأنها قيمة null عادية بلا UX أو error policy."]'::jsonb, '["كيف تختبر contract بين Dart وimplementation native لكل منصة؟"]'::jsonb, '[{"title":"Flutter docs — Build for and integrate with multiple platforms","url":"https://docs.flutter.dev/platform-integration"},{"title":"Flutter docs — Writing custom platform-specific code","url":"https://docs.flutter.dev/platform-integration/platform-channels"},{"title":"Flutter docs — Using packages and plugins","url":"https://docs.flutter.dev/packages-and-plugins/using-packages"}]'::jsonb from public.question_revisions r where r.question_id = 'platform-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'platform-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إمتى تختار plugin جاهزًا أو custom platform integration؟' or l.short_answer is distinct from 'ابدأ بـFlutter API أو plugin موثوق، واكتب integration مخصصًا فقط عندما توجد capability حقيقية غير مغطاة، مع عزل اختلافات المنصات خلف contract واحد.' or l.explanation is distinct from 'الـplugin الجاهز يقلل native code والصيانة، لكن يجب فحص المنصات المدعومة والـlifecycle وجودة الصيانة. عند الحاجة المخصصة، يمكن بناء plugin أو channel وربط Dart بالـhost، مع تنفيذ fallback أو رفض واضح للمنصة غير المدعومة. هذا قرار boundary وتكلفة ملكية، وليس قاعدة أن package واحدة أفضل دائمًا.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إضافة native code قبل التحقق من Flutter API أو plugin مناسب.","كشف تفاصيل Android وiOS في كل مستهلك بدل adapter واحد.","التعامل مع capability غير المدعومة كأنها قيمة null عادية بلا UX أو error policy."]'::jsonb or l.follow_up_questions is distinct from '["كيف تختبر contract بين Dart وimplementation native لكل منصة؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Build for and integrate with multiple platforms","url":"https://docs.flutter.dev/platform-integration"},{"title":"Flutter docs — Writing custom platform-specific code","url":"https://docs.flutter.dev/platform-integration/platform-channels"},{"title":"Flutter docs — Using packages and plugins","url":"https://docs.flutter.dev/packages-and-plugins/using-packages"}]'::jsonb)) then raise exception 'Question platform-002 ar content changed; create a new revision before seeding'; end if; end $$;
