insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إمتى تستخدم StatelessWidget وإيه معنى build بتاعها؟', 'StatelessWidget يصف UI اعتمادًا على configuration ثابتة، وbuild ترجع شجرة Widgets جديدة عندما يطلب Flutter تحديثها.', 'Stateless لا يعني أن الواجهة لن تتغير؛ يمكن أن تتغير عندما تتغير المدخلات أو يعيد parent البناء. لا تضع state متغيرة داخلها، ومرّر القيمة الجديدة من الخارج بدل mutation مخفي.', 'class Greeting extends StatelessWidget {
  const Greeting({super.key, required this.name});
  final String name;

  @override
  Widget build(BuildContext context) => Text("Hello $name");
}', '["اعتبار StatelessWidget غير قابل لإعادة البناء.","تخزين mutable state داخله بدل تمريرها كـparameters."]'::jsonb, '["متى يكون const constructor مفيدًا في StatelessWidget؟"]'::jsonb, '[{"title":"Flutter API — StatelessWidget","url":"https://api.flutter.dev/flutter/widgets/StatelessWidget-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'widgets-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'widgets-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إمتى تستخدم StatelessWidget وإيه معنى build بتاعها؟' or l.short_answer is distinct from 'StatelessWidget يصف UI اعتمادًا على configuration ثابتة، وbuild ترجع شجرة Widgets جديدة عندما يطلب Flutter تحديثها.' or l.explanation is distinct from 'Stateless لا يعني أن الواجهة لن تتغير؛ يمكن أن تتغير عندما تتغير المدخلات أو يعيد parent البناء. لا تضع state متغيرة داخلها، ومرّر القيمة الجديدة من الخارج بدل mutation مخفي.' or l.code_example is distinct from 'class Greeting extends StatelessWidget {
  const Greeting({super.key, required this.name});
  final String name;

  @override
  Widget build(BuildContext context) => Text("Hello $name");
}' or l.common_mistakes is distinct from '["اعتبار StatelessWidget غير قابل لإعادة البناء.","تخزين mutable state داخله بدل تمريرها كـparameters."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون const constructor مفيدًا في StatelessWidget؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter API — StatelessWidget","url":"https://api.flutter.dev/flutter/widgets/StatelessWidget-class.html"}]'::jsonb)) then raise exception 'Question widgets-001 ar content changed; create a new revision before seeding'; end if; end $$;
