insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'اشرح lifecycle الأساسي لـ StatefulWidget State؟', 'State يمر عادةً بـinitState ثم didChangeDependencies وbuild، وقد يستقبل didUpdateWidget، ثم dispose عند الإزالة النهائية.', 'ضع initialization مرة واحدة في initState، وتابع Inherited dependencies في didChangeDependencies، ونظّف controllers وlisteners في dispose. لا تنفذ side effects داخل build لأنها قد تتكرر.', null, '["إنشاء subscription داخل build.","نسيان dispose لـAnimationController أو StreamSubscription."]'::jsonb, '["متى يُستدعى didUpdateWidget؟"]'::jsonb, '[{"title":"Flutter API — State lifecycle","url":"https://api.flutter.dev/flutter/widgets/State-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'widgets-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'widgets-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'اشرح lifecycle الأساسي لـ StatefulWidget State؟' or l.short_answer is distinct from 'State يمر عادةً بـinitState ثم didChangeDependencies وbuild، وقد يستقبل didUpdateWidget، ثم dispose عند الإزالة النهائية.' or l.explanation is distinct from 'ضع initialization مرة واحدة في initState، وتابع Inherited dependencies في didChangeDependencies، ونظّف controllers وlisteners في dispose. لا تنفذ side effects داخل build لأنها قد تتكرر.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إنشاء subscription داخل build.","نسيان dispose لـAnimationController أو StreamSubscription."]'::jsonb or l.follow_up_questions is distinct from '["متى يُستدعى didUpdateWidget؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter API — State lifecycle","url":"https://api.flutter.dev/flutter/widgets/State-class.html"}]'::jsonb)) then raise exception 'Question widgets-002 ar content changed; create a new revision before seeding'; end if; end $$;
