insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'اشرح قاعدة constraints go down, sizes go up في Flutter؟', 'الـparent يرسل قيودًا للـchild، والـchild يختار size داخلها، ثم يضعه parent في مكانه.', 'حل مشاكل overflow يبدأ بقراءة constraints الفعلية، لا بإضافة Expanded عشوائيًا. Widget لا يختار حجمًا خارج الحد الذي أعطاه parent، وبعض parents مثل Column قد ترسل قيودًا غير محدودة في محور معين.', null, '["افتراض أن child يفرض حجمه على parent.","إخفاء overflow بـSingleChildScrollView بلا فهم سبب القيود."]'::jsonb, '["لماذا يفشل Expanded داخل Column في بعض الحالات؟"]'::jsonb, '[{"title":"Flutter docs — Understanding constraints","url":"https://docs.flutter.dev/ui/layout/constraints"}]'::jsonb from public.question_revisions r where r.question_id = 'widgets-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
