insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إمتى تستخدم InheritedWidget وdidChangeDependencies؟', 'InheritedWidget يشارك قيمة عبر الشجرة، وdidChangeDependencies تنبه State عندما تتغير dependency سجّلها عبر context.', 'استخدمه لقيمة مشتركة تتغير مع الزمن مثل Theme أو locale، وسجّل القراءة في build أو didChangeDependencies. لا تجعل InheritedWidget مخزنًا عامًا لكل state؛ اجعل نطاقه واضحًا واستعمل API متخصصة عندما تكبر المتطلبات.', null, '["قراءة dependency في initState فقط رغم أنها قد تتغير.","تمرير كل بيانات التطبيق عبر InheritedWidget واحد ضخم."]'::jsonb, '["ما الذي يجعل dependOnInheritedWidgetOfExactType يعيد الإشعار؟"]'::jsonb, '[{"title":"Flutter API — InheritedWidget","url":"https://api.flutter.dev/flutter/widgets/InheritedWidget-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'widgets-009' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
