insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما trade-offs استخدام GlobalKey في Flutter؟', 'GlobalKey تعطي وصولًا وهوية فريدة عبر الشجرة، لكنها أغلى وأشد coupling من local keys ويجب ألا تُنشأ داخل build.', 'استخدم GlobalKey عند حاجة حقيقية مثل الوصول إلى FormState أو نقل subtree، وثبّت instance في State أو owner مناسب. في القوائم استخدم ValueKey غالبًا، لأن GlobalKey كثيرة تصعّب المطابقة وتؤثر على الأداء.', null, '["إنشاء GlobalKey جديدة في كل build.","استخدامها كبديل لتمرير callback أو state بطريقة واضحة."]'::jsonb, '["كيف تستبدل GlobalKey بواجهة أبسط في نموذج صغير؟"]'::jsonb, '[{"title":"Flutter API — GlobalKey","url":"https://api.flutter.dev/flutter/widgets/GlobalKey-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'widgets-010' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
