insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه الفرق بين local state وshared state في Flutter؟', 'local state تخص Widget أو feature صغيرة، أما shared state فتحتاجها أجزاء متعددة أو شاشات مختلفة وتتطلب مالكًا ونطاقًا أوضح.', 'ابدأ بأقرب owner للحالة؛ لا ترفع قيمة لا يحتاجها غير child واحد. اجعل shared state صريحة في حدود feature، واحتفظ بالحالة المؤقتة مثل اختيار tab محلية ما لم يوجد سبب حقيقي لمشاركتها.', null, '["وضع كل state في singleton عالمي.","اعتبار كل قيمة داخل الشاشة app state."]'::jsonb, '["ما العلامة التي تقول إن local state يجب أن تصبح shared؟"]'::jsonb, '[{"title":"Flutter docs — Ephemeral vs app state","url":"https://docs.flutter.dev/data-and-backend/state-mgmt/ephemeral-vs-app"}]'::jsonb from public.question_revisions r where r.question_id = 'state-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
