insert into public.interview_questions (id, slug, track_id, difficulty) values ('state-002', 'lifting-state-up-in-flutter', 'flutter', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('state-002', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تطبق lifting state up بين Widgets؟', 'انقل state إلى أقرب parent مشترك يحتاج قراءتها أو تعديلها، ثم مرّر القيمة وcallbacks إلى children.', 'الـparent يصبح مصدر الحقيقة الواحد، وchildren تعرض البيانات أو تطلب تغييرها عبر callback. ارفع state تدريجيًا؛ رفعها إلى أعلى التطبيق من البداية يزيد التمرير والاقتران.', 'class Parent extends StatefulWidget {
  const Parent({super.key});
  @override State<Parent> createState() => _ParentState();
}

class _ParentState extends State<Parent> {
  int count = 0;
  @override Widget build(BuildContext context) => Child(
    value: count,
    onChanged: (value) => setState(() => count = value),
  );
}', '["امتلاك نفس state في child وparent معًا.","تمرير callbackات كثيرة بدل تحديد owner واحد."]'::jsonb, '["متى يصبح prop drilling إشارة لاختيار shared state؟"]'::jsonb, '[{"title":"Flutter docs — Lifting state up","url":"https://docs.flutter.dev/data-and-backend/state-mgmt/simple#lifting-state-up"}]'::jsonb from public.question_revisions r where r.question_id = 'state-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'state-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تطبق lifting state up بين Widgets؟' or l.short_answer is distinct from 'انقل state إلى أقرب parent مشترك يحتاج قراءتها أو تعديلها، ثم مرّر القيمة وcallbacks إلى children.' or l.explanation is distinct from 'الـparent يصبح مصدر الحقيقة الواحد، وchildren تعرض البيانات أو تطلب تغييرها عبر callback. ارفع state تدريجيًا؛ رفعها إلى أعلى التطبيق من البداية يزيد التمرير والاقتران.' or l.code_example is distinct from 'class Parent extends StatefulWidget {
  const Parent({super.key});
  @override State<Parent> createState() => _ParentState();
}

class _ParentState extends State<Parent> {
  int count = 0;
  @override Widget build(BuildContext context) => Child(
    value: count,
    onChanged: (value) => setState(() => count = value),
  );
}' or l.common_mistakes is distinct from '["امتلاك نفس state في child وparent معًا.","تمرير callbackات كثيرة بدل تحديد owner واحد."]'::jsonb or l.follow_up_questions is distinct from '["متى يصبح prop drilling إشارة لاختيار shared state؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Lifting state up","url":"https://docs.flutter.dev/data-and-backend/state-mgmt/simple#lifting-state-up"}]'::jsonb)) then raise exception 'Question state-002 ar content changed; create a new revision before seeding'; end if; end $$;
