insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ليه immutable state وchange notification مهمين؟', 'نسخة state جديدة مع إشعار واضح تجعل التغيير قابلًا للتتبع وتمنع المستهلكين من رؤية mutation جزئية أو مخفية.', 'عرّف state كقيمة تصف الحالة الحالية، ثم استبدلها عند التغيير وأبلغ listeners مرة واحدة. لو استخدمت mutable collections احمِها من التعديل الخارجي أو انسخها عند إنشاء state الجديدة.', null, '["تعديل List داخل state من غير إشعار.","إطلاق notifications متعددة لعملية منطقية واحدة بلا حاجة."]'::jsonb, '["ما الفرق بين equality بالمرجع وequality بالقيمة عند مقارنة state؟"]'::jsonb, '[{"title":"Flutter API — ValueNotifier","url":"https://api.flutter.dev/flutter/foundation/ValueNotifier-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'state-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
