insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'اشرح unidirectional data flow في تطبيق Flutter؟', 'البيانات تنزل من owner إلى UI، والأحداث تصعد كـintent؛ owner يحدّث state ثم يعيد نشر snapshot جديدة.', 'هذا الاتجاه يجعل مصدر الحقيقة ومسار التغيير واضحين: UI لا تعدّل model مباشرة، بل ترسل event أو command. استخدمه لتقليل التحديثات المتبادلة، مع إبقاء التدفق بسيطًا في features الصغيرة.', null, '["تعديل shared model من أي Widget مباشرة.","إضافة طبقات event ضخمة لزر واحد بلا فائدة."]'::jsonb, '["كيف تمنع event قديمًا من الكتابة فوق state أحدث؟"]'::jsonb, '[{"title":"Flutter docs — Unidirectional data flow","url":"https://docs.flutter.dev/app-architecture/concepts#unidirectional-data-flow"}]'::jsonb from public.question_revisions r where r.question_id = 'state-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
