insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('nav-001', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي يشتغل route stack في Navigator؟', 'Navigator يحتفظ بمكدس routes؛ push يضيف شاشة، وpop يزيل الحالية ويرجع لما تحتها.', 'تعامل مع route كحالة تنقل لها owner واضح، وتحقق من canPop قبل pop عندما لا تضمن وجود route سابقة. لا تضع side effects في build لمجرد فتح شاشة.', 'Navigator.of(context).push(
  MaterialPageRoute(builder: (_) => const DetailsPage()),
