do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'net-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ليه نعمل JSON serialization إلى typed models؟' or l.short_answer is distinct from 'typed model يضع contract للبيانات ويعزل parsing عن UI، فيكشف الحقول المفقودة أو المتغيرة قبل انتشارها في التطبيق.' or l.explanation is distinct from 'تحقق من nullability والأنواع عند boundary الشبكة، واحتفظ بتحويل JSON في data layer. generator أو parsing يدوي كلاهما خيار؛ القرار يعتمد على حجم schema وتكرارها وليس على package واحدة.' or l.code_example is distinct from 'factory User.fromJson(Map<String, Object?> json) => User(
