insert into public.interview_questions (id, slug, track_id, difficulty) values ('net-004', 'network-timeouts-and-retry-boundaries', 'flutter', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
