insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'فين تحط timeout وretry في network client؟', 'ضع timeout عند boundary الخارجية، واجعل retry محدودًا ومشروطًا بأخطاء مؤقتة مع backoff وبدون تكرار side effects خطرة.', 'حدّد budget زمنيًا للمحاولة، وسجّل سبب الانقطاع، ولا تعيد POST غير idempotent بلا idempotency key أو عقد واضح. لا تجعل كل UI يقرر سياسة retry الخاصة به.', null, '["retry فوري بلا حد فيزيد الحمل.","إخفاء timeout كأنه response فارغ."]'::jsonb, '["كيف تختار retryable status codes؟"]'::jsonb, '[{"title":"Dart API — Future.timeout","url":"https://api.dart.dev/dart-async/Future/timeout.html"},{"title":"RFC 9110 — HTTP Semantics","url":"https://www.rfc-editor.org/rfc/rfc9110#name-retry-after"}]'::jsonb from public.question_revisions r where r.question_id = 'net-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
