insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه دور integration test ومتى يستحق تكلفته؟', 'integration test يتحقق من flow كامل عبر التطبيق والمنصة مثل تسجيل الدخول أو الدفع، لكنه أبطأ وأكثر اعتمادًا على environment.', 'استخدمه للمخاطر التي لا تكشفها unit أو widget tests، وحدد بيانات test وحالة الجهاز بوضوح. لا تحوّل كل assertion إلى integration؛ احتفظ بمعظم feedback في اختبارات أسرع.', null, '["تشغيل integration suite لكل تغيير صغير.","ترك backend أو device state غير محدد فيؤدي إلى نتائج متذبذبة."]'::jsonb, '["كيف تقلل زمن integration suite من غير حذف التغطية المهمة؟"]'::jsonb, '[{"title":"Flutter docs — Integration testing","url":"https://docs.flutter.dev/cookbook/testing/integration/introduction"}]'::jsonb from public.question_revisions r where r.question_id = 'test-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
