insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تخلي اختبارات Flutter reliable وغير flaky؟', 'اعزل الوقت والعشوائية والشبكة، وانتظر condition واضحة بأدوات الاختبار بدل sleep، ونظّف resources وtest data بعد كل حالة.', 'اختبار موثوق يملك environment معروفًا ويكشف failure بدل ابتلاعه. استخدم test binding وأدوات الانتظار عند الحاجة، وقلّل الاعتماد على ترتيب الاختبارات أو حالة جهاز مشتركة.', null, '["إضافة delay أطول لإخفاء race condition.","ترك singleton أو subscription من test يؤثر في التالي."]'::jsonb, '["كيف تفرق بين flaky test وbug حقيقي في التطبيق؟"]'::jsonb, '[{"title":"Flutter docs — Testing overview","url":"https://docs.flutter.dev/testing"},{"title":"Flutter API — WidgetTester.pumpAndSettle","url":"https://api.flutter.dev/flutter/flutter_test/WidgetTester/pumpAndSettle.html"}]'::jsonb from public.question_revisions r where r.question_id = 'test-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'test-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تخلي اختبارات Flutter reliable وغير flaky؟' or l.short_answer is distinct from 'اعزل الوقت والعشوائية والشبكة، وانتظر condition واضحة بأدوات الاختبار بدل sleep، ونظّف resources وtest data بعد كل حالة.' or l.explanation is distinct from 'اختبار موثوق يملك environment معروفًا ويكشف failure بدل ابتلاعه. استخدم test binding وأدوات الانتظار عند الحاجة، وقلّل الاعتماد على ترتيب الاختبارات أو حالة جهاز مشتركة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["إضافة delay أطول لإخفاء race condition.","ترك singleton أو subscription من test يؤثر في التالي."]'::jsonb or l.follow_up_questions is distinct from '["كيف تفرق بين flaky test وbug حقيقي في التطبيق؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Testing overview","url":"https://docs.flutter.dev/testing"},{"title":"Flutter API — WidgetTester.pumpAndSettle","url":"https://api.flutter.dev/flutter/flutter_test/WidgetTester/pumpAndSettle.html"}]'::jsonb)) then raise exception 'Question test-005 ar content changed; create a new revision before seeding'; end if; end $$;
