insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ليه نعمل profiling قبل ما نحسّن أداء Flutter؟', 'القياس يحدد المرحلة والـdevice والـcode path المكلف بدل تخمين optimization قد لا يغيّر تجربة المستخدم.', 'قِس في profile mode وعلى جهاز قريب من الواقع، ثم قارن baseline واضحًا مثل frame time أو memory. لا تستنتج من debug logs أو microbenchmark صغير أن التطبيق كله بطيء.', null, '["تحسين كود لمجرد أنه يبدو معقدًا.","القياس على debug ثم نشر نتيجة غير قابلة للمقارنة."]'::jsonb, '["ما الفرق بين jank في build وjank في raster؟"]'::jsonb, '[{"title":"Flutter docs — Performance profiling","url":"https://docs.flutter.dev/perf/ui-performance"}]'::jsonb from public.question_revisions r where r.question_id = 'perf-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'perf-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ليه نعمل profiling قبل ما نحسّن أداء Flutter؟' or l.short_answer is distinct from 'القياس يحدد المرحلة والـdevice والـcode path المكلف بدل تخمين optimization قد لا يغيّر تجربة المستخدم.' or l.explanation is distinct from 'قِس في profile mode وعلى جهاز قريب من الواقع، ثم قارن baseline واضحًا مثل frame time أو memory. لا تستنتج من debug logs أو microbenchmark صغير أن التطبيق كله بطيء.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تحسين كود لمجرد أنه يبدو معقدًا.","القياس على debug ثم نشر نتيجة غير قابلة للمقارنة."]'::jsonb or l.follow_up_questions is distinct from '["ما الفرق بين jank في build وjank في raster؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Performance profiling","url":"https://docs.flutter.dev/perf/ui-performance"}]'::jsonb)) then raise exception 'Question perf-001 ar content changed; create a new revision before seeding'; end if; end $$;
