insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إمتى تستخدم ListView.builder بدل بناء قائمة كاملة؟', 'builder ينشئ children عند الحاجة، فيقلل الذاكرة والعمل الأولي للقوائم الكبيرة أو غير المحدودة.', 'استخدم itemBuilder وitemCount مع keys مستقرة عند الحاجة، وتجنب تحميل كل العناصر في Column أو ListView children دفعة واحدة. لا تستخدم lazy builder إذا كانت القائمة صغيرة وثابتة بلا مشكلة قياس.', null, '["تنفيذ network أو parsing داخل itemBuilder في كل build.","استخدام index كهوية لعناصر يمكن إعادة ترتيبها."]'::jsonb, '["كيف تتعامل مع pagination وloading item؟"]'::jsonb, '[{"title":"Flutter cookbook — Place items on demand","url":"https://docs.flutter.dev/cookbook/lists/long-lists"}]'::jsonb from public.question_revisions r where r.question_id = 'perf-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
