insert into public.interview_questions (id, slug, track_id, difficulty) values ('perf-004', 'avoiding-expensive-work-in-build', 'flutter', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('perf-004', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تمنع expensive work داخل build؟', 'احسب أو حمّل البيانات خارج build، استخدم memoization أو state مناسبة، وقلّل subtree الذي يعاد بناؤه بدل إخفاء العمل في helper.', 'build قد تتكرر أكثر مما تتوقع، لذلك لا تضع sort كبيرًا أو JSON parsing أو I/O داخلها. انقل العمل إلى repository أو controller، ثم قِس قبل إضافة cache حتى لا تخزن بيانات بلا فائدة.', null, '["تسمية function بـget ثم تنفيذ network داخلها أثناء build.","إضافة cache عالمي قبل معرفة تكلفة العمل."]'::jsonb, '["متى يكون Selector أو child subtree مفيدًا؟"]'::jsonb, '[{"title":"Flutter docs — Performance best practices","url":"https://docs.flutter.dev/perf/best-practices"}]'::jsonb from public.question_revisions r where r.question_id = 'perf-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'perf-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تمنع expensive work داخل build؟' or l.short_answer is distinct from 'احسب أو حمّل البيانات خارج build، استخدم memoization أو state مناسبة، وقلّل subtree الذي يعاد بناؤه بدل إخفاء العمل في helper.' or l.explanation is distinct from 'build قد تتكرر أكثر مما تتوقع، لذلك لا تضع sort كبيرًا أو JSON parsing أو I/O داخلها. انقل العمل إلى repository أو controller، ثم قِس قبل إضافة cache حتى لا تخزن بيانات بلا فائدة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تسمية function بـget ثم تنفيذ network داخلها أثناء build.","إضافة cache عالمي قبل معرفة تكلفة العمل."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون Selector أو child subtree مفيدًا؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Performance best practices","url":"https://docs.flutter.dev/perf/best-practices"}]'::jsonb)) then raise exception 'Question perf-004 ar content changed; create a new revision before seeding'; end if; end $$;
