insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تفسر مشاكل أداء الصور والذاكرة في Flutter؟', 'افصل حجم الملف عن حجم الصورة المفكوكة في الذاكرة، واستخدم caching وresize مناسبين للعرض بدل تحميل أصل ضخم لكل device.', 'راقب memory وraster time عند عرض صور كثيرة، وحدد cache policy وlifecycle. تحسين جودة الصورة أو ضغطها لا يكفي إذا كان decode dimensions أكبر بكثير من مكانها على الشاشة.', null, '["اعتبار ملف JPEG صغيرًا يعني استهلاك ذاكرة صغير.","إزالة كل caching ثم إعادة تنزيل الصور في كل rebuild."]'::jsonb, '["متى تستخدم cacheWidth أو thumbnails؟"]'::jsonb, '[{"title":"Flutter docs — Performance best practices","url":"https://docs.flutter.dev/perf/best-practices"},{"title":"Flutter API — Image constructor","url":"https://api.flutter.dev/flutter/widgets/Image/Image.html"},{"title":"Flutter API — ResizeImage","url":"https://api.flutter.dev/flutter/painting/ResizeImage-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'perf-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'perf-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تفسر مشاكل أداء الصور والذاكرة في Flutter؟' or l.short_answer is distinct from 'افصل حجم الملف عن حجم الصورة المفكوكة في الذاكرة، واستخدم caching وresize مناسبين للعرض بدل تحميل أصل ضخم لكل device.' or l.explanation is distinct from 'راقب memory وraster time عند عرض صور كثيرة، وحدد cache policy وlifecycle. تحسين جودة الصورة أو ضغطها لا يكفي إذا كان decode dimensions أكبر بكثير من مكانها على الشاشة.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اعتبار ملف JPEG صغيرًا يعني استهلاك ذاكرة صغير.","إزالة كل caching ثم إعادة تنزيل الصور في كل rebuild."]'::jsonb or l.follow_up_questions is distinct from '["متى تستخدم cacheWidth أو thumbnails؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Performance best practices","url":"https://docs.flutter.dev/perf/best-practices"},{"title":"Flutter API — Image constructor","url":"https://api.flutter.dev/flutter/widgets/Image/Image.html"},{"title":"Flutter API — ResizeImage","url":"https://api.flutter.dev/flutter/painting/ResizeImage-class.html"}]'::jsonb)) then raise exception 'Question perf-005 ar content changed; create a new revision before seeding'; end if; end $$;
