insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي يشتغل Dart event loop والفرق بين microtask وevent queue؟', 'isolate يعالج microtask queue قبل event queue؛ الإفراط في microtasks أو عمل CPU متواصل قد يمنع events ويفسد استجابة UI.', 'Future callbacks وtimers تُجدول بدل تنفيذها فورًا في نفس stack، لكن scheduling لا يجعل العمل CPU-bound مجانيًا. افهم ترتيب التسجيل والـqueues قبل تفسير race أو frame delay.', null, '["اعتبار async/await thread جديدًا.","إضافة microtask loop طويل ثم الاستغراب من توقف input."]'::jsonb, '["متى ينفذ Timer مقارنة بـFuture.microtask؟"]'::jsonb, '[{"title":"Dart docs — Concurrency","url":"https://dart.dev/language/concurrency"}]'::jsonb from public.question_revisions r where r.question_id = 'async-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
