insert into public.interview_questions (id, slug, track_id, difficulty) values ('async-004', 'isolates-for-cpu-bound-work', 'flutter', 'Senior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('async-004', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى تنقل CPU-bound work إلى isolate؟', 'انقل parsing أو compression أو خوارزمية ثقيلة إلى isolate عندما تثبت أنها تحجب UI isolate، وتبادل رسائل أو نتائج قابلة للنقل.', 'isolate يملك memory وevent loop منفصلين، لذلك لا تشارك mutable state مباشرة. ابدأ بقياس frame impact، واستخدم compute أو Isolate.run للحالات المناسبة على native؛ في Flutter Web قد يعمل compute على event loop الحالي، وتجنب تكلفة spawn لعمل صغير.', null, '["استخدام isolate لكل Future صغير.","افتراض أن timeout يلغي compute أو Isolate.run؛ الإلغاء الحقيقي يحتاج isolate مملوكًا يمكن إيقافه."]'::jsonb, '["ما تكلفة إنشاء isolate ومتى تفضل worker طويل العمر؟"]'::jsonb, '[{"title":"Dart docs — Isolates","url":"https://dart.dev/language/isolates"}]'::jsonb from public.question_revisions r where r.question_id = 'async-004' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'async-004' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'متى تنقل CPU-bound work إلى isolate؟' or l.short_answer is distinct from 'انقل parsing أو compression أو خوارزمية ثقيلة إلى isolate عندما تثبت أنها تحجب UI isolate، وتبادل رسائل أو نتائج قابلة للنقل.' or l.explanation is distinct from 'isolate يملك memory وevent loop منفصلين، لذلك لا تشارك mutable state مباشرة. ابدأ بقياس frame impact، واستخدم compute أو Isolate.run للحالات المناسبة على native؛ في Flutter Web قد يعمل compute على event loop الحالي، وتجنب تكلفة spawn لعمل صغير.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["استخدام isolate لكل Future صغير.","افتراض أن timeout يلغي compute أو Isolate.run؛ الإلغاء الحقيقي يحتاج isolate مملوكًا يمكن إيقافه."]'::jsonb or l.follow_up_questions is distinct from '["ما تكلفة إنشاء isolate ومتى تفضل worker طويل العمر؟"]'::jsonb or l.sources is distinct from '[{"title":"Dart docs — Isolates","url":"https://dart.dev/language/isolates"}]'::jsonb)) then raise exception 'Question async-004 ar content changed; create a new revision before seeding'; end if; end $$;
