insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('async-005', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تستخدم Future.wait بأمان مع أكثر من عملية async؟', 'أنشئ أو ابدأ الـFutures المطلوبة ثم مرّرها إلى Future.wait لتجميع النتائج، مع تحديد سياسة الخطأ وعدم تشغيل عمليات تعتمد على ترتيب سابق.', 'Future.wait ينتظر Futures الموجودة ولا يبدأ العمل بنفسه؛ استخدمه عندما لا توجد dependency بين الطلبات، ثم تعامل مع أول خطأ والموارد التي بدأت بالفعل. لا تستخدمه لتوازي CPU-bound work؛ Future scheduling لا يخلق isolate جديدًا.', null, '["تشغيل عمليات تعتمد على نتيجة سابقة داخل Future.wait.","اعتبار فشل Future.wait إلغاءً تلقائيًا لكل العمليات الأخرى."]'::jsonb, '["متى تفضّل تنفيذ العمليات بالتتابع؟"]'::jsonb, '[{"title":"Dart API — Future.wait","url":"https://api.dart.dev/dart-async/Future/wait.html"}]'::jsonb from public.question_revisions r where r.question_id = 'async-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'async-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تستخدم Future.wait بأمان مع أكثر من عملية async؟' or l.short_answer is distinct from 'أنشئ أو ابدأ الـFutures المطلوبة ثم مرّرها إلى Future.wait لتجميع النتائج، مع تحديد سياسة الخطأ وعدم تشغيل عمليات تعتمد على ترتيب سابق.' or l.explanation is distinct from 'Future.wait ينتظر Futures الموجودة ولا يبدأ العمل بنفسه؛ استخدمه عندما لا توجد dependency بين الطلبات، ثم تعامل مع أول خطأ والموارد التي بدأت بالفعل. لا تستخدمه لتوازي CPU-bound work؛ Future scheduling لا يخلق isolate جديدًا.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تشغيل عمليات تعتمد على نتيجة سابقة داخل Future.wait.","اعتبار فشل Future.wait إلغاءً تلقائيًا لكل العمليات الأخرى."]'::jsonb or l.follow_up_questions is distinct from '["متى تفضّل تنفيذ العمليات بالتتابع؟"]'::jsonb or l.sources is distinct from '[{"title":"Dart API — Future.wait","url":"https://api.dart.dev/dart-async/Future/wait.html"}]'::jsonb)) then raise exception 'Question async-005 ar content changed; create a new revision before seeding'; end if; end $$;
